package it.noxia.ambientplayer;
import org.junit.Test;import static org.junit.Assert.*;
public class MusicLinksTest {
 @Test public void originalAndMorpheUseExactYoutubeVideoId(){for(String source:new String[]{MusicSources.YOUTUBE,MusicSources.MORPHE})assertEquals("https://music.youtube.com/watch?v=dQw4w9WgXcQ",MusicLinks.track(source,null,"dQw4w9WgXcQ"));}
 @Test public void spotifyUsesItsOwnTrackUri(){assertEquals("spotify:track:4cOdK2wGLETKBW3PvgPWqT",MusicLinks.track(MusicSources.SPOTIFY,null,"4cOdK2wGLETKBW3PvgPWqT"));assertEquals("spotify:track:4cOdK2wGLETKBW3PvgPWqT",MusicLinks.track(MusicSources.SPOTIFY,null,"spotify:track:4cOdK2wGLETKBW3PvgPWqT"));}
 @Test public void publishedTrackUrlsAreRetainedForOtherProviders(){String[][] cases={{MusicSources.APPLE,"https://music.apple.com/it/album/test/123?i=456"},{MusicSources.APPLE,"https://music.apple.com/us/song/test/456"},{MusicSources.TIDAL,"https://tidal.com/browse/track/123"},{MusicSources.DEEZER,"https://www.deezer.com/it/track/123"},{MusicSources.AMAZON,"https://music.amazon.it/albums/B012345678?trackAsin=B000000001"}};for(String[] c:cases)assertEquals(c[1],MusicLinks.track(c[0],c[1],null));}
 @Test public void mediaUriWinsOverOpaqueMetadataId(){String link="https://www.deezer.com/track/123";assertEquals(link,MusicLinks.track(MusicSources.DEEZER,link,"private-id"));}
 @Test public void anotherProvidersLinkCannotBeOpened(){assertNull(MusicLinks.track(MusicSources.TIDAL,"https://www.deezer.com/track/123",null));assertNull(MusicLinks.track(MusicSources.BITCHORD,null,"dQw4w9WgXcQ"));}
 @Test public void unsafeAndImpersonatingUrlsAreRejected(){for(String url:new String[]{"intent://track/123#Intent;end","file:///private/test","content://media/1","https://music.apple.com.evil.test/it/song/a/123","https://music.apple.com@evil.test/it/song/a/123","https://evil@music.apple.com/it/song/a/123","https://music.apple.com:9000/it/song/a/123"})assertNull(url,MusicLinks.track(MusicSources.APPLE,url,null));}
 @Test public void appHomeAlbumAndSearchAreNotTrackLinks(){assertNull(MusicLinks.track(MusicSources.APPLE,"https://music.apple.com/it/album/test/123",null));assertNull(MusicLinks.track(MusicSources.SPOTIFY,"https://open.spotify.com/",null));assertNull(MusicLinks.track(MusicSources.YOUTUBE,"https://music.youtube.com/search?q=test",null));}
 @Test public void opaqueIdsDoNotBecomeGuessedSongs(){for(String source:new String[]{MusicSources.YOUTUBE,MusicSources.SPOTIFY,MusicSources.APPLE,MusicSources.TIDAL,MusicSources.DEEZER,MusicSources.AMAZON})assertNull(source,MusicLinks.track(source,null,"id-100"));}
 @Test public void unknownSourceAndEmptyDataCannotCreateNavigation(){assertNull(MusicLinks.track("unknown","https://music.youtube.com/watch?v=dQw4w9WgXcQ",null));assertNull(MusicLinks.track(null,null,null));}
}
